#include "HierarchyMachine.h"
static void Log(ESCX_StateMachine*m,int v){HierarchyData*d=(HierarchyData*)m->instance;d->log[d->count++]=v;}
static void ER(ESCX_StateMachine*m,void*d){(void)d;Log(m,1);} static void XR(ESCX_StateMachine*m,void*d){(void)d;Log(m,-1);}
static void EP(ESCX_StateMachine*m,void*d){(void)d;Log(m,2);} static void XP(ESCX_StateMachine*m,void*d){(void)d;Log(m,-2);}
static void EA(ESCX_StateMachine*m,void*d){(void)d;Log(m,3);} static void XA(ESCX_StateMachine*m,void*d){(void)d;Log(m,-3);}
static void EB(ESCX_StateMachine*m,void*d){(void)d;Log(m,4);} static void XB(ESCX_StateMachine*m,void*d){(void)d;Log(m,-4);}
static void EO(ESCX_StateMachine*m,void*d){(void)d;Log(m,5);} static void XO(ESCX_StateMachine*m,void*d){(void)d;Log(m,-5);}
static void Act(ESCX_StateMachine*m,void*d){(void)d;Log(m,9);}
